{
  "packet_hash": "cb880398fd50b73e1c1e61c2285288c215637bc61d380bc822416e9f8ca54235",
  "author": "elf/b/round-1 independent discovery",
  "parent_revision": 0,
  "title": "橙酔も複製する四連レイピア：コンボエルフの1枠拡張",
  "hypothesis": "ローテーション・エルフ。標準コンボエルフにスターライトゴッデス1枚を置き、山札で強化した緑風のレイピア使い2枚と、手札で軽減した緋岸橙酔1枚を一緒に複製する。レイピア4回を同一ターンに払い切れる形へし、橙酔2枚を大型守護の処理・ドロー・コンボの最初の2プレイへ兼用する。攻撃5のレイピア4枚と0PP橙酔2枚なら、選択・破壊可能な守護2枚を処理した後に8PP・20打点を出せる指定状態がある。勝率・到達頻度・新発見は未確認。通常構築に対して、超進化権や3枚目のレイピアを引けない終盤の別ルートを1枠で持つことを試す種。",
  "change": "初回考案中にWebで『ゴッデス採用レイピア複製バフエルフ』の先行例を確認したため、レイピア複製自体の新規性主張を撤回した。発展点を、緋岸橙酔という第9弾の札を第三の複製対象にして、コピー後の打点を止める守護と開始2プレイを同じ札で処理する配分へ絞った。単なるレイピア2回増加の説明ではなく、4回の実支払と手札上限を検算した。正式な改訂・別評価はまだない。",
  "roles": [
    {
      "card_id": 10714110,
      "role": "山札に残っているレイピアを強化する基盤。3枚を維持。クレストを複製して重ねる案ではない。",
      "access": "deck"
    },
    {
      "card_id": 10712110,
      "role": "2PPの疾走受け皿。3枚を維持し、強化後に引いた2枚をゴッデスで各1枚複製して計4回使う。追加2枚はゴッデスの効果で得る同カード。",
      "access": "deck"
    },
    {
      "card_id": 10502110,
      "role": "実質1枠の追加。残した左3枚の状態をコピーする。捨て札3枚と手動進化権を別に払う。",
      "access": "deck"
    },
    {
      "card_id": 10913310,
      "role": "2枚を維持。4回のコンボ3ターン終了を手札で見て0PPになった個体を第三対象にし、コピーで追加1枚を得る。",
      "access": "deck"
    },
    {
      "card_id": 10913110,
      "role": "既存のコンボ3ドロー。強化後の札を探す。引く札の指定はできず、レイピア2枚の確保を保証しない。",
      "access": "deck"
    },
    {
      "card_id": 10912110,
      "role": "既存の序盤フォロワーとフェアリー生成。フェアリーはコンボ・防御にも必要で、捨て札に回す価値を毎回差し引く。",
      "access": "deck"
    },
    {
      "card_id": 10514120,
      "role": "既存のPP回復・フェアリー生成・割りふり除去。各モードは同時に全部使わない。",
      "access": "deck"
    },
    {
      "card_id": 10714120,
      "role": "既存の森の神秘供給と除去。コピー対象が揃わない時も通常のコンボを支える。",
      "access": "deck"
    },
    {
      "card_id": 90011110,
      "role": "根差の刺客またはミロクから得る突進札。防御、コンボ、余剰時の捨て札候補。",
      "access": "effect",
      "via": [
        10912110,
        10514120
      ]
    },
    {
      "card_id": 90011310,
      "role": "鹿王から得る0PPの別の開始札。相手に橙酔の対象が少ない場合の候補だが、必要枚数の保持は別条件。",
      "access": "effect",
      "via": [
        10714120
      ]
    },
    {
      "card_id": 10914110,
      "role": "既存の盤面処理と超進化疾走。コピーが揃わない時の主要打点として3枚を維持。",
      "access": "deck"
    },
    {
      "card_id": 10814110,
      "role": "通常の疾走・大型破壊・守護・盤面強化。基準の3枚から2枚に減らす具体的な交換元。",
      "access": "deck"
    }
  ],
  "steps": [
    {
      "action": "準備条件A：ダストデイズを手札から4PPでプレイし、EP1を使って進化する。クレストの有効な3回のターン終了でそれぞれコンボ3を達成する。後攻T4の例なら、本体でコンボ2になった後、前半エクストラPP1で1コスト札を追加すれば最初の1回を満たせる。この例は必要札を引いている条件付き。",
      "resources": "本体分PP4、EP1。後攻T4例ではPP4→0→エクストラで1→1コスト札で0。手札は本体と追加札の2枚を使用し、追加札の個別ドロー等は別会計。場には本体用1枠と追加フォロワーならもう1枠が必要。コンボは本体のプレイ1＋能力1＋追加プレイ1＝3。T5/T6の2回分も実際に3コンボを要し、無料達成や本体生存を仮定しない。",
      "result": "3回の終了処理中ずっと山札にいたレイピアは元の2/2から5/5となる。その後に2枚を引く必要がある。先に手札へ来たものへ残りの山札バフは乗らない。同名クレストの重複は数えない。",
      "evidence": [
        {
          "card_id": 10714110,
          "field": "skill_text",
          "quote": "自分の【コンボ】を+1する。"
        },
        {
          "card_id": 10714110,
          "field": "skill_text",
          "quote": "【進化時】自分は『クレスト：操嵩のアナテマ・ダストデイズ』を持つ。"
        },
        {
          "card_id": 10714110,
          "field": "ref_effect_text",
          "quote": "【カウントダウン_3】\n自分のターン終了時、【コンボ_3】自分のデッキのフォロワーすべては+1/+1する。"
        }
      ]
    },
    {
      "action": "準備条件B：緋岸橙酔を手札に保持したまま、自分のターン終了時コンボ3を4回満たす。例えばT4〜T7の4回ならT8に0PPとなるが、このターン列の到達を保証しない。枝葉の舎弟頭等で強化後のレイピア2枚を探す。",
      "resources": "橙酔の手札枠1を複数ターン占有。コスト4→3→2→1→0。軽減に直接のPP支払はないが、各ターンのコンボ3に使うカードとPPは別途必要。枝葉は2PP、手札から1枚を使い、コンボ3で2枚引くため当該解決の純増1。最大手札9と場5を越えないよう先に札を使う。進化権は後のゴッデス用にEP1を残す条件。",
      "result": "0PP橙酔と強化後レイピア2枚が揃った時だけコピーへ移る。橙酔の軽減に『ターン終了まで』はなく、固定注記の状態コピーを適用する。ヒエンの一時軽減を次ターンまで保存する案ではない。",
      "evidence": [
        {
          "card_id": 10913310,
          "field": "skill_text",
          "quote": "手札で働く。自分のターン終了時、【コンボ_3】これのコストを-1する。"
        },
        {
          "card_id": 10913110,
          "field": "skill_text",
          "quote": "【ファンファーレ】【コンボ_3】自分のデッキから2枚を引く。"
        },
        {
          "card_id": 10502110,
          "field": "note",
          "quote": "状態ごとコピー(スペブ回数・融合カウント・バフ込み)+同名3枚制限の実質突破が本体。手札6枚以上が実質要求"
        }
      ]
    },
    {
      "action": "指定状態からの検算例：T8の通常ドロー後、手札7枚を『ゴッデス1、5/5レイピア2、0PP橙酔1、捨てる他3』とし、場0、EP1、生存している状態で開始する。ゴッデスを5PPでプレイしEP進化。他3枚を選んで捨て、残った3枚をコピーする。手札を自由に並べ替えたとは扱わず、他3枚を除いた結果として左3枚を一意にする。",
      "resources": "PP8→3。手札7→プレイ後6→捨てた後3→コピー後6。場0→1。EP1→0。捨て札は例えば余剰フェアリーと使い所を失った序盤札であり、無価値・無償とはしない。EPは準備Aの1と今回1で合計2。SEPはこの手順では未使用。",
      "result": "手札は5/5レイピア4枚、0PP橙酔2枚となる。生成先は元の手札2枚のレイピアと1枚の橙酔で、カード本文・固定noteを根拠に状態もコピーする。ゴッデスの場残り・攻撃は次ターンの20点に算入しない。",
      "evidence": [
        {
          "card_id": 10502110,
          "field": "skill_text",
          "quote": "【進化時】自分の手札3枚を選ぶ。それを捨てる。自分の手札左から3枚のコピー1枚ずつを非公開で自分の手札に加える。"
        },
        {
          "card_id": 10502110,
          "field": "note",
          "quote": "状態ごとコピー(スペブ回数・融合カウント・バフ込み)"
        },
        {
          "keyword": "進化時",
          "quote": "EPを使って進化したときやSEPを使って超進化したときに働く能力。"
        }
      ]
    },
    {
      "action": "相手ターンを生き延びたT9の例。通常ドロー後手札7。相手の場に選択・破壊可能な守護2体があり、破壊後に新たな守護や打点妨害を生まないとする。橙酔2枚をその2体に順に使用する。手札破壊等による妨害がないことも前提。",
      "resources": "開始PP9、コンボ0、手札7、自場0〜1。橙酔は各0PPで2枚使用し2枚引くので手札は各解決後7のまま、コンボ0→1→2、PP9のまま。山札は通常ドローとこの2枚分の合計3枚以上を残す。橙酔はスペルなので場枠を増やさない。",
      "result": "対象の大型守護2体を処理して、疾走条件の前2プレイも満たす。オーラや破壊不能にはこの選択破壊を適用しない。破壊対象が2枚ない盤面では、この指定手順をそのまま実行できるとは言わない。",
      "evidence": [
        {
          "card_id": 10913310,
          "field": "skill_text",
          "quote": "相手の場のフォロワー1枚を選ぶ。それを破壊。自分のデッキから1枚を引く。"
        },
        {
          "keyword": "オーラ",
          "quote": "相手の能力で選ばれない。"
        }
      ]
    },
    {
      "action": "レイピア4枚を2PPずつ手札からプレイし、各個体で相手リーダーを1回攻撃する。以降の守護・ダメージ軽減・攻撃制限がなく、相手の体力が20以下である条件。",
      "resources": "各プレイ後のコンボ3/4/5/6、残PP7/5/3/1、手札6/5/4/3。自場は開始1以下なら最終5以下。EP/SEPは使わない。4個体をプレイするので、同一個体の再攻撃でも無限ループでもない。",
      "result": "5×4＝20打点、橙酔を含めて消費8PP。1回のバフ不足で各4なら16点、各3なら12点。橙酔が各1PPなら計10PP、各2なら計12PPなのでT9の同じ例に当てはめない。これは指定状態の成立で、T9到達率の主張ではない。",
      "evidence": [
        {
          "card_id": 10712110,
          "field": "skill_text",
          "quote": "【ファンファーレ】【コンボ_3】これは【疾走】を持つ。"
        },
        {
          "keyword": "コンボ",
          "quote": "「このターン中に自分がプレイしたカードの数」を表す。\nこの値が指定された値以上のときに働く能力もある。"
        },
        {
          "keyword": "疾走",
          "quote": "場に出たターンでも攻撃できる。"
        },
        {
          "source_hash": "c3f61931bad245924922be51e0346407abdb01535d1299ac012cbb218086286f",
          "quote": "各5打点が通れば計20。決着ターンにEP/SEPを使わず、前ターンの味方の生存打点も加えていない。"
        }
      ]
    },
    {
      "action": "通常構築との比較と停止分岐。必要札・手札位置・余剰3枚・進化権が揃わない、または準備ターンに守り切れないと判断したらコピーを待たず通常の攻めへ移る。",
      "resources": "追加の採用はゴッデス1枠。コピー時は5PP＋進化権1＋捨て札3が負担。2回目のダストデイズ進化や防御へのEP使用と競合する。通常構築の最大打点と同一の手札条件であるとは扱わない。",
      "result": "通常構築にはレイピア3枚＋超進化マガチヨ等で上回る打点もある。今回の価値仮説は最大値更新ではなく、既存の強化・軽減を使って、2枚のレイピアとEPを終盤に別の打点・大型守護処理へ変える選択肢。採用負担に見合う頻度は未確認のまま別担当へ渡す。",
      "evidence": [
        {
          "card_id": 10814110,
          "field": "skill_text",
          "quote": "【ファンファーレ】相手の場のフォロワー1枚を選ぶ。それを破壊。自分の場の他のフォロワーすべては+1/+1する。"
        },
        {
          "source_hash": "c3f61931bad245924922be51e0346407abdb01535d1299ac012cbb218086286f",
          "quote": "通常構築は攻撃5レイピア3枚＋攻撃8の超進化マガチヨで、コンボ開始札を別に用意すれば9PP・23点を出せるので、提案が一律に最大打点や速度で上とは言わない。"
        },
        {
          "source_hash": "4fdf04c3261776aed79e0df095aafc77c70ec883f45e75b60ce3ba4a129c471f",
          "quote": "したがって、ゴッデスでレイピアを増やすこと自体を今回の新発見とは扱わない。"
        }
      ]
    }
  ],
  "plan": {
    "early": "大遊戯世界、低コストフォロワー、ミロク、枝葉のドローで通常のコンボ基盤を回す。ゴッデスを初手から優先保持する方針にはせず、ダストデイズを探す。ササニドはドレインを使う通常役として残るが、信仰10達成や天槍の深淵の早期生成をこの案の前提にしない。",
    "transition": "ダストデイズの山札強化と、手札の橙酔軽減を同じコンボ3の継続で進める。後半に強化済みレイピアを2枚引き、余剰手札3枚と進化権がある局面だけゴッデスへ移る。8PP準備→9PP決着は例示で、最速ターンや安定ターンではない。",
    "finish": "主な追加枝は橙酔2枚で大きい守護を処理しながらコンボ2、その後レイピア4回。敵のフォロワーが2枚未満なら、保持できている森の神秘等を前2プレイに使えるかを再計算する。必要な開始札がない場合は20点を主張せず、通常の分割打点へ切り替える。",
    "without_core": "ゴッデスを引けなければ従来通り、強化レイピア・超進化マガチヨ・残したセタス＆メイシアで攻める。橙酔が軽くならなくても既存の除去として使う。ダストデイズを引けない時は小型盤面からマガチヨの超進化疾走やセタスの疾走で削るが、強化不足で出力は下がる。無強化レイピア4枚を20点と数えず、コピーのために勝てる通常手順を遅らせない。",
    "allocation": "比較元は保存GameWithコンボエルフ40枚（source_hash=82e99a39d9f2e4fc0ff8c0cbc33b9f5ab727e47dc2728881bc829b348d5e0335）。セタス＆メイシア3→2、スターライトゴッデス0→1の1枠案。ダストデイズ3、レイピア3、橙酔2と既存ドロー・生成源を維持する。失うのはセタス1枚分の即時大型破壊、疾走4以上、守護、他の味方+1/+1。専用の捨て札カードを追加せず、既存の余剰手札を使うが、それらの防御・コンボ・回復を失う損失は残る。全40枚を完成・実証済みとする提案ではない。",
    "comparison": "山札バフ＋疾走は保存された標準用法。レイピア複製にもWeb上の先行言及があるため既出。今回の着眼は第9弾の橙酔を同時複製し、第三枠を除去・ドロー・開始札へ重ねること。通常構築の1枠で試せる可能性と、3枚目のレイピアや決着時のSEPに頼らない枝を得る点を採用理由とする。ただし5PPの準備と進化権1、手札の形を揃える負担があり、普通にマガチヨ等を引けている時は通常構築の方が速く強いことがある。先行例の全40枚がないため、その先行構築に対する厳密な新しい差分は未確認。"
  },
  "questions": [
    {
      "question": "2枚のレイピアを十分な山札バフ後に引き、軽減済み橙酔と捨て札3枚とゴッデスを、負けずに同時保持できる頻度はどれくらいか。",
      "tag": null,
      "why": "指定状態の20点より、5PPの準備を払う機会が1枠の損失に見合うかが試行価値を決める。"
    },
    {
      "question": "先行するレイピア複製バフエルフの原リスト・手順に、今回の第三枠の兼用が既に含まれているか。",
      "tag": null,
      "why": "先行例の存在は確認したが全40枚は未取得。同じ使い方なら独自性の根拠をさらに狭める必要がある。"
    },
    {
      "question": "現在の実機または公式Q&Aで、ダストデイズ由来の手札バフと緋岸橙酔の永続的コスト軽減がコピーへ保持されることを再確認できるか。",
      "tag": null,
      "why": "固定資料noteは状態ごとコピーを明示しているが、今回の公式openではQ&A本文を取得できなかった。"
    }
  ],
  "uncertainties": [
    "対戦・勝率・到達率の測定はない。有用性の別評価は依頼どおり未実施。",
    "初回の考案内で枝を変更したが、正式提出後の追加開発・改訂は未実施。",
    "指定手札を自然に引ける保証はなく、先引きレイピアはバフ不足となる。橙酔を守りのため途中で使うとコピー対象を失う。",
    "コピー準備ターンを生き延びる必要がある。ゴッデスや他の味方の翌ターン生存を打点に足していない。",
    "手札位置、余剰3枚、進化権の競合は採用負担。ゴッデスの自動進化では進化時コピーは誘発しない。",
    "破壊・選択不能、追加守護、リーダーダメージ軽減、手札妨害には指定手順が破綻し得る。",
    "空盤面で橙酔の使用対象がなく、別の開始札もない場合は四連20点を実行できない。",
    "先行例の言及だけで未普及とも強いとも判定しない。検索結果に同じ第三枠用法を確認できなかったことは未発見の証明ではない。"
  ],
